exercises.starter:
SELECT department_id, first_name, salary FROM (
  SELECT department_id, first_name, salary,
    ROW_NUMBER() OVER (PARTITION BY department_id ORDER BY salary DESC, id) AS r
  FROM employees
) WHERE r = 2;

exercises.sql:
SELECT MAX(r) FROM (
  SELECT DENSE_RANK() OVER (ORDER BY v DESC) AS r
  FROM (SELECT 10 AS v UNION ALL SELECT 9 UNION ALL SELECT 9 UNION ALL SELECT 8)
);

